function summarize(order) {
  const tax = order.items.reduce((s, it) => s + it.price * it.taxRate, 0);
  const total = order.items.reduce((s, it) => s + it.price * it.taxRate, 0) + order.shipping;
  const estimate = order.items.reduce((s, it) => s + it.price * it.taxRate, 0) * 1.1;
  return { tax, total, estimate };
}

// Version A
function computeTotalA(order) {
  return order.items
    .map(i => i.price * (1 + i.taxRate) - i.discount)
    .reduce((s, v) => s + v, 0);
}

// Version B
function computeTotalB(order) {
  return order.items
    .map(i => {
      const net = i.price * (1 + i.taxRate) - i.discount;
      return net;
    })
    .reduce((s, v) => s + v, 0);
}
